function computeAssetFilenames(project) {
  const map = {};
  // These names are reserved by the Zepp OS package metadata.
  // A user asset must never be allowed to shadow the application icon
  // or watchface preview generated by the exporter.
  const used = new Set(['icon.png', 'Preview.png', 'preview_en.png']);
  for (const a of project.assets || []) {
    const ext = a.format === 'JPEG' ? 'jpg' : 'png';
    const base = sanitizeAssetFilename(a.name);
    let filename = `${base}.${ext}`;
    let i = 2;
    while (used.has(filename)) { filename = `${base}_${i}.${ext}`; i++; }
    used.add(filename);
    map[a.id] = filename;
  }
  return map;
}

function computeFontFilenames(project) {
  const map = {};
  for (const f of project.fonts || []) {
    const safe = (f.filename || `${f.name || f.id}.ttf`).replace(/[^a-zA-Z0-9._-]+/g, '_');
    map[f.id] = `fonts/${f.id}_${safe}`;
  }
  return map;
}

// ---------------------------------------------------------------------------
// index-js-exporter.js
//
// Генерирует watchface/index.js — код циферблата Zepp OS API 3.0 в ESM-стиле
// (см. ZEPP_API_COMPONENTS.md): import из '@zos/ui' / '@zos/sensor' /
// '@zos/timer', WatchFace({ build() {...}, onDestroy() {...} }).
//
// Свойства, не подтверждённые официальной документацией (см. registry.js,
// поле confidence: 'unverified'), реализуются рабочим кодом с защитой
// try/catch и явным TODO-комментарием — вместо того, чтобы не работать
// вовсе. Список таких мест дублируется в validation.warnings.
// ---------------------------------------------------------------------------

function jsStr(s) { return JSON.stringify(String(s == null ? '' : s)); }
function jsNum(n, fallback = 0) { const v = Number(n); return Number.isFinite(v) ? Math.round(v) : fallback; }

function colorLiteral(hex) {
  let clean = String(hex || '#ffffff').trim().replace('#', '');
  // Поддержка короткой формы #rgb -> rrggbb (каждая цифра дублируется),
  // как это делают браузерные <input type="color"> значения при ручной правке.
  if (/^[0-9a-fA-F]{3}$/.test(clean)) clean = clean.split('').map((c) => c + c).join('');
  if (!/^[0-9a-fA-F]{6}$/.test(clean)) clean = 'ffffff';
  return `0x${clean}`;
}

function alignConst(v, fallback) { return `align.${v || fallback}`; }
function textStyleConst(v) { return `text_style.${v || 'NONE'}`; }

function objLit(pairs) {
  const parts = pairs.filter(Boolean).map(([k, v]) => `${k}: ${v}`);
  return `{ ${parts.join(', ')} }`;
}

// Унифицирует поля форматирования времени/даты независимо от того, откуда
// они взяты: у пресетов (time_hm, date_full, ...) это одно общее поле
// `format`, а у универсального TEXT с data_source это именованные поля
// (time_format, date_format, ...) — см. DATA_SOURCES в registry.js.
function timeParams(comp, def) {
  const p = comp.props || {};
  const isPreset = def.id !== 'text';
  return {
    timeFormat: isPreset ? (p.format || 'HH:MM') : (p.time_format || 'HH:MM'),
    timeLeadingZero: isPreset ? true : (p.time_leading_zero !== false),
    timeSeparator: isPreset ? ':' : (p.time_separator ?? ':'),
    ampmCase: p.ampm_case || 'AM/PM',
    dateFormat: isPreset ? (p.format || 'DD.MM.YYYY') : (p.date_format || 'DD.MM.YYYY'),
    dateLocale: p.date_locale || 'EN',
    weekdayFormat: isPreset ? (p.format || 'EEE') : (p.weekday_format || 'EEE'),
    weekdayLocale: p.weekday_locale || 'EN',
    hourFormat: p.hour_format || 'HH',
    hourLeadingZero: p.hour_leading_zero !== false,
    minuteLeadingZero: p.minute_leading_zero !== false,
    secondLeadingZero: p.second_leading_zero !== false,
    dayLeadingZero: p.day_leading_zero !== false,
    monthFormat: p.month_format || 'MM',
    monthLocale: p.month_locale || 'EN',
    yearFormat: p.year_format || 'YYYY',
  };
}

function timeValueExpr(source, tp) {
  switch (source) {
    case 'TIME':
      return `formatClock(now, ${tp.timeFormat.startsWith('hh')}, ${tp.timeLeadingZero}, ${jsStr(tp.timeSeparator)}, ${tp.timeFormat.endsWith(':SS')})`;
    case 'AMPM':
      return `formatAmpm(now, ${jsStr(tp.ampmCase)})`;
    case 'DATE':
      return `formatDate(now, ${jsStr(tp.dateFormat)}, ${jsStr(tp.dateLocale)})`;
    case 'WEEKDAY':
      return `formatWeekday(now, ${jsStr(tp.weekdayFormat)}, ${jsStr(tp.weekdayLocale)})`;
    case 'HOUR':
      return `formatHour(now, ${jsStr(tp.hourFormat)}, ${tp.hourLeadingZero})`;
    case 'MINUTE':
      return `formatUnit(now.getMinutes(), ${tp.minuteLeadingZero})`;
    case 'SECOND':
      return `formatUnit(now.getSeconds(), ${tp.secondLeadingZero})`;
    case 'DAY':
      return `formatUnit(now.getDate(), ${tp.dayLeadingZero})`;
    case 'MONTH':
      return `formatMonth(now, ${jsStr(tp.monthFormat)}, ${jsStr(tp.monthLocale)})`;
    case 'YEAR':
      return `formatYear(now, ${jsStr(tp.yearFormat)})`;
    default:
      return null;
  }
}

const TIME_SOURCES = new Set(['TIME', 'AMPM', 'DATE', 'WEEKDAY', 'HOUR', 'MINUTE', 'SECOND', 'DAY', 'MONTH', 'YEAR']);
const SENSOR_SOURCES = new Set(['BATTERY', 'STEP', 'HEART', 'CALORIE', 'DISTANCE', 'WEATHER_TEMP', 'WEATHER_ICON']);

const TIME_HELPERS_SRC = `
const WD_EN = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
const WD_EN_FULL = ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
const WD_RU = ['ВС', 'ПН', 'ВТ', 'СР', 'ЧТ', 'ПТ', 'СБ'];
const WD_RU_3 = ['ВОС', 'ПОН', 'ВТР', 'СРД', 'ЧТВ', 'ПТН', 'СБТ'];
const WD_RU_FULL = ['ВОСКРЕСЕНЬЕ', 'ПОНЕДЕЛЬНИК', 'ВТОРНИК', 'СРЕДА', 'ЧЕТВЕРГ', 'ПЯТНИЦА', 'СУББОТА'];
const MO_EN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const MO_EN_FULL = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const MO_RU = ['янв', 'фев', 'мар', 'апр', 'май', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
const MO_RU_FULL = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];

function pad2(n) { n = Math.floor(n); return n < 10 ? ('0' + n) : String(n); }
function formatUnit(n, lead) { return lead ? pad2(n) : String(Math.floor(n)); }
function formatClock(now, hour12, lead, sep, withSeconds) {
  let h = now.getHours();
  if (hour12) { h = h % 12; if (h === 0) h = 12; }
  let out = (lead ? pad2(h) : String(h)) + sep + pad2(now.getMinutes());
  if (withSeconds) out += sep + pad2(now.getSeconds());
  return out;
}
function formatAmpm(now, caseOpt) {
  const v = now.getHours() < 12 ? 'AM' : 'PM';
  return caseOpt === 'am/pm' ? v.toLowerCase() : v;
}
function formatHour(now, fmt, lead) {
  let h = now.getHours();
  if (fmt === 'hh') { h = h % 12; if (h === 0) h = 12; }
  return lead ? pad2(h) : String(h);
}
function formatDate(now, fmt, locale) {
  const MS = locale === 'RU' ? MO_RU : MO_EN, MF = locale === 'RU' ? MO_RU_FULL : MO_EN_FULL;
  const dd = pad2(now.getDate()), mm = pad2(now.getMonth() + 1), yyyy = String(now.getFullYear());
  if (fmt === 'DD MMM') return dd + ' ' + MS[now.getMonth()];
  if (fmt === 'MMM DD') return MS[now.getMonth()] + ' ' + dd;
  if (fmt === 'DD MMMM') return dd + ' ' + MF[now.getMonth()];
  if (fmt === 'DD/MM') return dd + '/' + mm;
  if (fmt === 'YYYY-MM-DD') return yyyy + '-' + mm + '-' + dd;
  return dd + '.' + mm + '.' + yyyy;
}
function formatWeekday(now, fmt, locale) {
  const W = locale === 'RU' ? (fmt === 'EEEE' ? WD_RU_FULL : (fmt === 'EEE3' ? WD_RU_3 : WD_RU)) : (fmt === 'EEEE' ? WD_EN_FULL : WD_EN);
  return W[now.getDay()];
}
function formatMonth(now, fmt, locale) {
  const MS = locale === 'RU' ? MO_RU : MO_EN, MF = locale === 'RU' ? MO_RU_FULL : MO_EN_FULL;
  if (fmt === 'MMM') return MS[now.getMonth()];
  if (fmt === 'MMMM') return MF[now.getMonth()];
  if (fmt === 'M') return String(now.getMonth() + 1);
  return pad2(now.getMonth() + 1);
}
function formatYear(now, fmt) {
  const y = now.getFullYear();
  return fmt === 'YY' ? String(y).slice(-2) : String(y);
}
`.trim();

const WEATHER_ICON_FILES = [
  '0_cloudy.png', '1_showers.png', '2_snow_showers.png', '3_sunny.png', '4_overcast.png',
  '5_light_rain.png', '6_light_snow.png', '7_moderate_rain.png', '8_moderate_snow.png', '9_heavy_snow.png',
  '10_heavy_rain.png', '11_sandstorm.png', '12_rain_snow.png', '13_fog.png', '14_hazy.png',
  '15_thunderstorm.png', '16_snowstorm.png', '17_floating_dust.png', '18_very_heavy_rainstorm.png',
  '19_rain_hail.png', '20_thunderstorm_hail.png', '21_heavy_rainstorm.png', '22_dust.png', '23_heavy_sandstorm.png',
  '24_rainstorm.png', '25_unknown.png', '26_cloudy_night.png', '27_showers_night.png', '28_sunny_night.png',
];

/**
 * Собирает watchface/index.js по состоянию проекта.
 * @param {object} project   store.state
 * @param {object} [assetMap] id ресурса -> имя файла в assets/<device>/ (если не передан — вычисляется)
 * @param {object} [fontMap]  id шрифта -> путь assets/<device>/fonts/... (если не передан — вычисляется)
 * @returns {{code: string, validation: {errors: string[], warnings: string[]}}}
 */
function exportIndexJs(project, assetMap, fontMap, options = {}) {
  assetMap = assetMap || computeAssetFilenames(project);
  fontMap = fontMap || computeFontFilenames(project);
  const namePrefix = String(options.namePrefix || '').replace(/[^a-zA-Z0-9_]/g, '_');
  const showLevel = options.showLevel || null;
  const weatherAssetMap = options.weatherAssetMap || {};

  const errors = [];
  const warnings = [];
  const unverifiedUsed = new Set();
  const assetsById = new Map((project.assets || []).map((a) => [a.id, a]));
  const device = project.device || { w: 480, h: 480 };
  const dw = jsNum(device.w, 480);
  const dh = jsNum(device.h, 480);

  const visibleComponents = (project.components || []).filter((c) => c.visible !== false);

  function resolveAsset(assetId, label) {
    if (!assetId) { errors.push(`${label}: не выбрано изображение.`); return null; }
    const a = assetsById.get(assetId);
    const filename = assetMap[assetId];
    if (!a || !filename) { errors.push(`${label}: ресурс-изображение не найден (id ${assetId}). Возможно, он был удалён.`); return null; }
    return { filename, width: jsNum(a.width, 64), height: jsNum(a.height, 64) };
  }

  function fontFieldFor(props) {
    if (!props.font) return null;
    const path = fontMap[props.font];
    if (!path) { warnings.push(`Компонент ссылается на несуществующий шрифт (id ${props.font}) — использован системный шрифт по умолчанию.`); return null; }
    return ['font', jsStr(path)];
  }

  // ---- сбор виджетов -------------------------------------------------
  const buildLines = [];      // createWidget(...) и прочий код внутри build()
  const timeUpdates = [];     // строки внутри _tick(), обновляются раз в секунду
  const sensorUpdates = [];   // строки внутри _tickSensors(), раз в 5 секунд
  const smoothLines = [];     // отдельный таймер плавной секундной стрелки
  let usesTimeHelpers = false;
  let usesHeartRate = false, usesStep = false, usesBattery = false, usesWeather = false;
  let usesCalorie = false, usesDistance = false;
  let usesWeatherIconFiles = false;
  let usesRouter = false;

  // Фон: заливка цветом и/или изображение под всеми виджетами.
  const bg = project.background || {};
  buildLines.push(`createWidget(widget.FILL_RECT, ${objLit([
    ['x', 0], ['y', 0], ['w', dw], ['h', dh], ['color', colorLiteral(bg.color || '#000000')],
  ])});`);
  if (bg.imageAssetId) {
    const bgAsset = resolveAsset(bg.imageAssetId, 'Фон циферблата');
    if (bgAsset) {
      buildLines.push(`createWidget(widget.IMG, ${objLit([
        ['x', 0], ['y', 0], ['w', dw], ['h', dh], ['src', jsStr(bgAsset.filename)],
      ])});`);
    }
  }

  // TIME_POINTER (часовая/минутная/[тиковая секундная]) собираются в ОДИН
  // createWidget — так требует hmUI.widget.TIME_POINTER (см. ZEPP_API_COMPONENTS.md).
  const pointerByRole = {};
  for (const comp of visibleComponents) {
    const def = REGISTRY[comp.defId];
    if (def && def.widgetId === 'TIME_POINTER') {
      const role = comp.defId === 'time_pointer_hour' ? 'hour' : comp.defId === 'time_pointer_minute' ? 'minute' : 'second';
      pointerByRole[role] = comp;
    }
  }
  const secondComp = pointerByRole.second;
  const secondSmooth = secondComp && secondComp.props && secondComp.props.motion === 'SMOOTH';
  if (secondSmooth) unverifiedUsed.add('TIME_POINTER (плавный ход секундной стрелки, ручная анимация)');


  const SYSTEM_METRIC_APPS = {
    STATUS: 'SYSTEM_APP_STATUS',
    HR: 'SYSTEM_APP_HR',
    SPORT: 'SYSTEM_APP_SPORT',
    WEATHER: 'SYSTEM_APP_WEATHER',
    SPORT_HISTORY: 'SYSTEM_APP_SPORT_HISTORY',
    PAI: 'SYSTEM_APP_PAI',
    SLEEP: 'SYSTEM_APP_SLEEP',
    SPO2: 'SYSTEM_APP_SPO2',
    CALENDAR: 'SYSTEM_APP_CALENDAR',
    MEASUREMENT: 'SYSTEM_APP_MEASUREMENT',
    READINESS: 'SYSTEM_APP_READINESS',
  };

  // The tap rectangle must match the editor's component hit box.
  // Most widgets use comp.x/y/w/h. Circle widgets are represented in the
  // editor by center_x/center_y/radius, so use that actual visual rectangle.
  // TIME_POINTER deliberately keeps comp.x/y/w/h as its editable tap zone:
  // a rotating hand cannot be represented by one static narrow rectangle.
  function tapRectForComponent(comp, def) {
    const p = comp.props || {};
    if (def && (def.widgetId === 'CIRCLE' || def.widgetId === 'STROKE_CIRCLE')) {
      const radius = Math.max(1, jsNum(p.radius, Number(comp.w || 20) / 2));
      const cx = jsNum(p.center_x, jsNum(comp.x, 0) + radius);
      const cy = jsNum(p.center_y, jsNum(comp.y, 0) + radius);
      return {
        x: Math.max(0, Math.round(cx - radius)),
        y: Math.max(0, Math.round(cy - radius)),
        w: Math.round(radius * 2),
        h: Math.round(radius * 2),
      };
    }

    const baseX = Math.max(0, jsNum(comp.x, 0));
    const baseY = Math.max(0, jsNum(comp.y, 0));
    const baseW = Math.max(1, jsNum(comp.w, 10));
    const baseH = Math.max(1, jsNum(comp.h, 10));

    const hasTapZone = Object.prototype.hasOwnProperty.call(p, 'tap_x') || Object.prototype.hasOwnProperty.call(p, 'tap_y') || Object.prototype.hasOwnProperty.call(p, 'tap_w') || Object.prototype.hasOwnProperty.call(p, 'tap_h');
    const rawTapX = Object.prototype.hasOwnProperty.call(p, 'tap_x') ? Number(p.tap_x) : null;
    const rawTapY = Object.prototype.hasOwnProperty.call(p, 'tap_y') ? Number(p.tap_y) : null;
    const rawTapW = Object.prototype.hasOwnProperty.call(p, 'tap_w') ? Number(p.tap_w) : null;
    const rawTapH = Object.prototype.hasOwnProperty.call(p, 'tap_h') ? Number(p.tap_h) : null;

    if (hasTapZone) {
      return {
        x: Math.max(0, Math.round(rawTapX ?? baseX)),
        y: Math.max(0, Math.round(rawTapY ?? baseY)),
        w: Math.max(1, Math.round(rawTapW ?? baseW)),
        h: Math.max(1, Math.round(rawTapH ?? baseH)),
      };
    }

    const source = def && (def.dataSource || (p && p.data_source)) ? (def.dataSource || p.data_source) : null;
    const liveTextTap = def && def.widgetId === 'TEXT' && source && (TIME_SOURCES.has(source) || SENSOR_SOURCES.has(source));
    if (!liveTextTap) {
      return { x: baseX, y: baseY, w: baseW, h: baseH };
    }

    const pad = Math.max(8, Math.min(24, Math.round(Math.min(baseW, baseH) * 0.25)));
    let rx = baseX + baseW + pad;
    let ry = baseY;
    if (rx + baseW > dw) {
      rx = Math.max(0, baseX - baseW - pad);
    }
    if (ry + baseH > dh) {
      ry = Math.max(0, baseY - baseH - pad);
    }
    const zoneW = Math.max(1, Math.min(baseW, dw - rx));
    const zoneH = Math.max(1, Math.min(baseH, dh - ry));
    return {
      x: Math.round(rx),
      y: Math.round(ry),
      w: zoneW,
      h: zoneH,
    };
  }

  function emitTapAction(comp, x, y, w, h) {
    const p = comp.props || {};
    const action = p.tap_action || 'NONE';
    if (action === 'NONE') return;

    usesRouter = true;
    const varName = `${namePrefix}tap_${String(comp.id || 'component').replace(/[^a-zA-Z0-9_]/g, '_')}`;
    let callback;
    if (action === 'APP') {
      const appId = jsNum(p.tap_app_id, 0);
      const url = p.tap_app_url || 'pages/index';
      if (!appId) {
        warnings.push(`Компонент ${comp.id}: для открытия приложения не задан App ID.`);
        return;
      }
      callback = `() => { launchApp({ appId: ${appId}, url: ${jsStr(url)} }); }`;
    } else if (action === 'METRIC') {
      const metric = p.tap_metric || 'STATUS';
      const systemId = SYSTEM_METRIC_APPS[metric];
      if (!systemId) return;
      callback = `() => { launchApp({ appId: ${systemId}, native: true }); }`;
    } else return;

    // Прозрачная BUTTON-зона. BUTTON — документированный способ получать tap/click,
    // а setAlpha(0) оставляет исходный компонент визуально неизменным.
    buildLines.push(`const ${varName} = createWidget(widget.BUTTON, ${objLit([
      ['x', x], ['y', y], ['w', w], ['h', h], ['text', jsStr('')],
      ['normal_color', '0x000000'], ['press_color', '0x000000'],
      ['click_func', callback],
    ])});`);
    buildLines.push(`${varName}.setAlpha(0);`);
  }

  // Три стрелки объединяются в ОДИН createWidget(widget.TIME_POINTER, {...}),
  // но их положение в порядке слоёв (относительно остальных виджетов) должно
  // соответствовать тому месту, где стрелки стоят в списке компонентов —
  // иначе они всегда рисуются раньше/позже, чем задумал пользователь, и
  // оказываются, например, под текстом. Поэтому объединённый виджет
  // эмитится прямо в основном цикле, в момент первой встреченной стрелки.
  function emitPointerGroup() {
    const pointerProps = [];
    for (const role of ['hour', 'minute', 'second']) {
      const comp = pointerByRole[role];
      if (!comp) continue;
      if (role === 'second' && secondSmooth) continue;
      const p = comp.props || {};
      const img = resolveAsset(p.path, `Стрелка (${role})`);
      if (!img) continue;
      pointerProps.push([`${role}_centerX`, jsNum(p.center_x, dw / 2)]);
      pointerProps.push([`${role}_centerY`, jsNum(p.center_y, dh / 2)]);
      pointerProps.push([`${role}_posX`, jsNum(p.pos_x, Math.round(img.width / 2))]);
      pointerProps.push([`${role}_posY`, jsNum(p.pos_y, Math.round(img.height / 2))]);
      pointerProps.push([`${role}_path`, jsStr(img.filename)]);
      if (p.cover_path) {
        const cover = resolveAsset(p.cover_path, `Накладка стрелки (${role})`);
        if (cover) pointerProps.push([`${role}_cover_path`, jsStr(cover.filename)]);
      }
    }
    if (pointerProps.length) {
      buildLines.push(`createWidget(widget.TIME_POINTER, ${objLit(pointerProps)});`);
    }
    if (secondSmooth) {
      const comp = secondComp;
      const p = comp.props || {};
      const img = resolveAsset(p.path, 'Секундная стрелка (плавный ход)');
      if (img) {
        const cx = jsNum(p.center_x, dw / 2), cy = jsNum(p.center_y, dh / 2);
        const px = jsNum(p.pos_x, Math.round(img.width / 2)), py = jsNum(p.pos_y, Math.round(img.height / 2));
        const stepDeg = Math.max(0, Number(p.smooth_step_deg) || 0);
        buildLines.push(`// Секундная стрелка: плавный ход не подтверждён официальной документацией`);
        buildLines.push(`// (⚠ unverified) — см. ZEPP_API_COMPONENTS.md. Реализована вручную поверх IMG.`);
        buildLines.push(`const ${namePrefix}w_second_smooth = createWidget(widget.IMG, ${objLit([
          // Контейнер IMG занимает весь циферблат, чтобы повёрнутая
          // стрелка не обрезалась границами маленького IMG.
          // Положение изображения задаётся ОДИН РАЗ и больше не меняется.
          ['x', 0], ['y', 0], ['w', dw], ['h', dh],
          ['src', jsStr(img.filename)],
          ['pos_x', cx - px], ['pos_y', cy - py],
          ['center_x', cx], ['center_y', cy],
        ])});`);
        smoothLines.push(`try {`);
        smoothLines.push(`  const now = new Date();`);
        smoothLines.push(`  let deg = (now.getSeconds() + now.getMilliseconds() / 1000) * 6;`);
        if (stepDeg > 0) smoothLines.push(`  deg = Math.round(deg / ${stepDeg}) * ${stepDeg};`);
        // Критически важно: x/y/pos_x/pos_y/center_x/center_y НИКОГДА
        // не пересчитываются во время анимации. Секундная стрелка находится
        // в центре циферблата постоянно; меняется только angle.
        smoothLines.push(`  ${namePrefix}w_second_smooth.setProperty(prop.MORE, { angle: deg });`);
        smoothLines.push(`} catch (e) {`);
        smoothLines.push(`  if (self._smoothTimer) { clearInterval(self._smoothTimer); self._smoothTimer = null; }`);
        smoothLines.push(`}`);
      }
    }
  }
  let pointerGroupEmitted = false;

  // Все виджеты — строго в порядке слоёв проекта (снизу вверх), включая
  // объединённую группу стрелок на месте первой встреченной стрелки.
  let widgetSeq = 0;
  for (const comp of visibleComponents) {
    const def = REGISTRY[comp.defId];
    if (!def) continue;
    if (def.widgetId === 'TIME_POINTER') {
      if (!pointerGroupEmitted) { emitPointerGroup(); pointerGroupEmitted = true; }
      continue;
    }
    const p = comp.props || {};
    const x = jsNum(comp.x, 0), y = jsNum(comp.y, 0), w = jsNum(comp.w, 10), h = jsNum(comp.h, 10);
    const varName = `${namePrefix}w_${widgetSeq++}_${sanitizeAssetFilename(comp.id || def.id, 'w').replace(/-/g, '_')}`;

    if (def.widgetId === 'FILL_RECT') {
      buildLines.push(`createWidget(widget.FILL_RECT, ${objLit([
        ['x', x], ['y', y], ['w', w], ['h', h], ['radius', jsNum(p.radius, 0)], ['color', colorLiteral(p.color)],
      ])});`);
    } else if (def.widgetId === 'STROKE_RECT') {
      unverifiedUsed.add('STROKE_RECT (прямоугольник-контур)');
      buildLines.push(`createWidget(widget.STROKE_RECT, ${objLit([
        ['x', x], ['y', y], ['w', w], ['h', h], ['radius', jsNum(p.radius, 0)],
        ['color', colorLiteral(p.color)], ['line_width', jsNum(p.line_width, 4)],
      ])});`);
    } else if (def.widgetId === 'CIRCLE') {
      unverifiedUsed.add('CIRCLE (круг-заливка)');
      buildLines.push(`createWidget(widget.CIRCLE, ${objLit([
        ['center_x', jsNum(p.center_x, x + w / 2)], ['center_y', jsNum(p.center_y, y + h / 2)],
        ['radius', jsNum(p.radius, w / 2)], ['color', colorLiteral(p.color)],
      ])});`);
    } else if (def.widgetId === 'STROKE_CIRCLE') {
      unverifiedUsed.add('STROKE_CIRCLE (круг-контур)');
      buildLines.push(`createWidget(widget.STROKE_CIRCLE, ${objLit([
        ['center_x', jsNum(p.center_x, x + w / 2)], ['center_y', jsNum(p.center_y, y + h / 2)],
        ['radius', jsNum(p.radius, w / 2)], ['color', colorLiteral(p.color)], ['line_width', jsNum(p.line_width, 4)],
      ])});`);
    } else if (def.widgetId === 'ARC') {
      buildLines.push(`createWidget(widget.ARC, ${objLit([
        ['x', x], ['y', y], ['w', w], ['h', h],
        ['start_angle', jsNum(p.start_angle, 0)], ['end_angle', jsNum(p.end_angle, 270)],
        ['color', colorLiteral(p.color)], ['line_width', jsNum(p.line_width, 8)],
      ])});`);
    } else if (def.widgetId === 'CANVAS') {
      buildLines.push(`const ${varName} = createWidget(widget.CANVAS, ${objLit([['x', x], ['y', y], ['w', w], ['h', h]])});`);
      buildLines.push(`// USER ANIMATION CODE CAN BE ADDED HERE (${varName}.drawLine/drawRect/drawCircle/drawArc/drawText/drawImage/...)`);
    } else if (def.widgetId === 'IMG' && def.id === 'weather_icon') {
      // Weather icons must be bound directly to the firmware weather data type.
      // Do NOT poll the deprecated Weather sensor and swap IMG.src manually:
      // the watch firmware already exposes the current weather index 0..28.
      usesWeather = true;
      usesWeatherIconFiles = true;
      const startId = normalizeWeatherIconId(p.src) || 'sunny';
      const startIdx = WEATHER_ICON_SET.findIndex((wc) => wc.id === startId);
      const startFile = WEATHER_ICON_FILES[startIdx >= 0 ? startIdx : 3];
      const iconArray = WEATHER_ICON_FILES.map((name) => jsStr(`weather/${name}`)).join(', ');
      buildLines.push(`const ${varName} = createWidget(widget.IMG_LEVEL, ${objLit([
        ['x', x], ['y', y], ['w', w], ['h', h], ['image_array', `[${iconArray}]`], ['image_length', '29'],
        ['type', 'data_type.WEATHER_CURRENT'], ['default_frame_index', String(startIdx >= 0 ? startIdx : 3)], ['alpha', jsNum(p.alpha, 100)],
      ])});`);
    } else if (def.widgetId === 'IMG') {
      const img = resolveAsset(p.src, `Изображение (${comp.id})`);
      if (img) {
        buildLines.push(`createWidget(widget.IMG, ${objLit([
          ['x', x], ['y', y], ['w', w], ['h', h], ['src', jsStr(img.filename)],
        ])});`);
      }
    } else if (def.widgetId === 'TEXT') {
      const dataSource = getEffectiveDataSource(comp, def) || 'NONE';
      const fontField = fontFieldFor(p);
      const baseProps = [
        ['x', x], ['y', y], ['w', w], ['h', h],
        ['text_size', jsNum(p.text_size, 32)], ['color', colorLiteral(p.color)],
        ['align_h', alignConst(p.align_h, 'CENTER_H')], ['align_v', alignConst(p.align_v, 'CENTER_V')],
        ['text_style', textStyleConst(p.text_style)],
        fontField,
      ];

      if (dataSource === 'WEATHER_TEMP') {
        // Use the watchface-specific TEXT_FONT binding. It reads the real
        // weather value from firmware and keeps the designer's TTF/color.
        // This avoids the deprecated @zos/sensor Weather forecast path.
        usesWeather = true;
        const mode = p.weather_temp_source || 'CURRENT';
        const type = mode === 'LOW' ? 'data_type.WEATHER_LOW' : (mode === 'HIGH' ? 'data_type.WEATHER_HIGH' : 'data_type.WEATHER_CURRENT');
        buildLines.push(`createWidget(widget.TEXT_FONT, ${objLit([
          ['x', x], ['y', y], ['w', w], ['h', h], ['text_size', jsNum(p.text_size, 32)],
          ['color', colorLiteral(p.color)], ['align_h', alignConst(p.align_h, 'CENTER_H')],
          ['align_v', alignConst(p.align_v, 'CENTER_V')], ['text_style', textStyleConst(p.text_style)],
          fontField, ['type', type], ['unit_type', p.weather_show_degree === false ? '0' : '1'],
        ])});`);
      } else if (TIME_SOURCES.has(dataSource)) {
        usesTimeHelpers = true;
        const tp = timeParams(comp, def);
        const expr = timeValueExpr(dataSource, tp);
        buildLines.push(`const ${varName} = createWidget(widget.TEXT, ${objLit([...baseProps, ['text', jsStr('')]])});`);
        timeUpdates.push(`${varName}.setProperty(prop.MORE, { text: ${expr} });`);
      } else if (SENSOR_SOURCES.has(dataSource)) {
        const prefix = p.prefix ?? '';
        const suffix = p.suffix ?? '';
        buildLines.push(`const ${varName} = createWidget(widget.TEXT, ${objLit([...baseProps, ['text', jsStr('--')]])});`);
        if (dataSource === 'BATTERY') {
          usesBattery = true;
          sensorUpdates.push(`try {`);
          sensorUpdates.push(`  const v = _battery ? _battery.getCurrent() : null;`);
          sensorUpdates.push(`  ${varName}.setProperty(prop.MORE, { text: (typeof v === 'number' ? ${jsStr(prefix)} + v + ${jsStr(suffix)} : '--') });`);
          sensorUpdates.push(`} catch (e) { ${varName}.setProperty(prop.MORE, { text: '--' }); }`);
        } else if (dataSource === 'STEP') {
          usesStep = true;
          const sep = p.step_thousands_sep ? 'true' : 'false';
          sensorUpdates.push(`try {`);
          sensorUpdates.push(`  const v = _step ? _step.getCurrent() : null;`);
          sensorUpdates.push(`  const txt = typeof v === 'number' ? (${sep} ? v.toLocaleString('en-US') : String(v)) : '--';`);
          sensorUpdates.push(`  ${varName}.setProperty(prop.MORE, { text: ${jsStr(prefix)} + txt + ${jsStr(suffix)} });`);
          sensorUpdates.push(`} catch (e) { ${varName}.setProperty(prop.MORE, { text: '--' }); }`);
        } else if (dataSource === 'HEART') {
          usesHeartRate = true;
          const minValid = jsNum(p.heart_min_valid, 30);
          sensorUpdates.push(`try {`);
          sensorUpdates.push(`  const v = _heart ? _heart.getCurrent() : null;`);
          sensorUpdates.push(`  const txt = (typeof v === 'number' && v >= ${minValid}) ? String(v) : '--';`);
          sensorUpdates.push(`  ${varName}.setProperty(prop.MORE, { text: ${jsStr(prefix)} + txt + ${jsStr(suffix)} });`);
          sensorUpdates.push(`} catch (e) { ${varName}.setProperty(prop.MORE, { text: '--' }); }`);
        } else if (dataSource === 'CALORIE') {
          // Калории — ОТДЕЛЬНЫЙ датчик Calorie из '@zos/sensor' (getCurrent(), ккал),
          // а не метод объекта Step: https://docs.zepp.com/docs/reference/device-app-api/newAPI/sensor/Calorie/
          usesCalorie = true;
          const decimals = jsNum(p.calorie_decimals, 0);
          sensorUpdates.push(`try {`);
          sensorUpdates.push(`  const v = _calorie ? _calorie.getCurrent() : null;`);
          sensorUpdates.push(`  const txt = typeof v === 'number' ? v.toFixed(${decimals}) : '--';`);
          sensorUpdates.push(`  ${varName}.setProperty(prop.MORE, { text: ${jsStr(prefix)} + txt + ${jsStr(suffix)} });`);
          sensorUpdates.push(`} catch (e) { ${varName}.setProperty(prop.MORE, { text: '--' }); }`);
        } else if (dataSource === 'DISTANCE') {
          // Дистанция — ОТДЕЛЬНЫЙ датчик Distance из '@zos/sensor' (getCurrent()):
          // https://docs.zepp.com/docs/reference/device-app-api/newAPI/sensor/Distance/
          usesDistance = true; unverifiedUsed.add('DISTANCE (единица измерения датчика — принята за метры)');
          const decimals = jsNum(p.distance_decimals, 2);
          const unit = (p.distance_unit || p.unit) || 'km';
          const isMiles = unit === 'mi';
          // У пресета «Расстояние» нет поля суффикса — подставляем выбранную единицу.
          const distSuffix = p.suffix ?? ` ${unit}`;
          sensorUpdates.push(`try {`);
          sensorUpdates.push(`  const raw = _distance ? _distance.getCurrent() : null;`);
          sensorUpdates.push(`  // Единица возвращаемого значения в документации не указана (⚠) — принята за метры.`);
          sensorUpdates.push(`  let v = typeof raw === 'number' ? raw / 1000 : null;`);
          if (isMiles) sensorUpdates.push(`  if (v !== null) v = v * 0.621371;`);
          sensorUpdates.push(`  const txt = v !== null ? v.toFixed(${decimals}) : '--';`);
          sensorUpdates.push(`  ${varName}.setProperty(prop.MORE, { text: ${jsStr(prefix)} + txt + ${jsStr(distSuffix)} });`);
          sensorUpdates.push(`} catch (e) { ${varName}.setProperty(prop.MORE, { text: '--' }); }`);
        }
      } else {
        buildLines.push(`createWidget(widget.TEXT, ${objLit([...baseProps, ['text', jsStr(p.text ?? '')]])});`);
      }
    }
  }

  // Зоны тапов создаются последними, поэтому они не меняют внешний вид компонентов
  // и находятся поверх всех визуальных элементов. При пересечении зон верхней будет
  // зона компонента, которая идёт позже в слоях проекта.
  for (const comp of visibleComponents) {
    const def = REGISTRY[comp.defId];
    const tapRect = tapRectForComponent(comp, def);
    emitTapAction(comp, tapRect.x, tapRect.y, tapRect.w, tapRect.h);
  }

  if (usesWeather) {
    warnings.push('Погода привязана напрямую к hmUI.data_type.WEATHER_CURRENT/WEATHER_LOW/WEATHER_HIGH и к системному индексу погоды 0..28. Значения зависят от синхронизации погоды часов с телефоном.');
  }
  if (unverifiedUsed.size) {
    warnings.push(`Использованы компоненты/свойства, не подтверждённые официальной документацией Zepp OS (⚠ unverified): ${[...unverifiedUsed].join('; ')}. Сверьте перед публикацией — см. README.md и ZEPP_API_COMPONENTS.md.`);
  }
  if (Number(project.app?.appId) === 10001 || !project.app?.appId) {
    warnings.push('appId в app.json — заглушка (10001). Перед публикацией замените на идентификатор из Zepp Developer Console.');
  }

  // ---- сборка исходного текста файла ---------------------------------
  // For the dual Normal/AOD export, the same watchface entry point creates
  // BOTH scene sets. Zepp OS selects visibility per widget via show_level.
  // This is preferable to branching on the current screen: the official
  // watchface AOD mechanism is a display level attached at widget creation.
  if (showLevel) {
    const levelExpr = `show_level.${showLevel}`;
    for (let i = 0; i < buildLines.length; i++) {
      buildLines[i] = buildLines[i].replace(
        /createWidget\((widget\.[A-Za-z0-9_]+), \{\s*/,
        (m) => m + `show_level: ${levelExpr},\n`
      );
    }
  }

  const importLines = [`import { createWidget, widget, align, text_style, prop, show_level, data_type } from '@zos/ui'`];
  if (usesRouter) importLines.push(`import { launchApp, SYSTEM_APP_STATUS, SYSTEM_APP_HR, SYSTEM_APP_SPORT, SYSTEM_APP_WEATHER, SYSTEM_APP_SPORT_HISTORY, SYSTEM_APP_PAI, SYSTEM_APP_SLEEP, SYSTEM_APP_SPO2, SYSTEM_APP_CALENDAR, SYSTEM_APP_MEASUREMENT, SYSTEM_APP_READINESS } from '@zos/router'`);
  const sensorImports = [];
  if (usesBattery) sensorImports.push('Battery');
  if (usesStep) sensorImports.push('Step');
  if (usesCalorie) sensorImports.push('Calorie');
  if (usesDistance) sensorImports.push('Distance');
  if (usesHeartRate) sensorImports.push('HeartRate');
  if (sensorImports.length) importLines.push(`import { ${sensorImports.join(', ')} } from '@zos/sensor'`);
  if (usesTimeHelpers || sensorImports.length || secondSmooth) importLines.push(`import { setInterval, clearInterval } from '@zos/timer'`);

  const parts = [];
  parts.push(importLines.join('\n'));
  parts.push('');
  if (usesTimeHelpers) { parts.push(TIME_HELPERS_SRC); parts.push(''); }
  if (usesWeatherIconFiles) {
    parts.push(`const WEATHER_ICON_FILES = ${JSON.stringify(WEATHER_ICON_FILES)};`);
    parts.push('');
  }
  if (sensorImports.length) {
    // ВАЖНО: переменные датчиков объявлены на уровне модуля, а не внутри build().
    // Вспомогательные функции ниже находятся в области видимости модуля, и если
    // датчик объявить локально в build(), они получат ReferenceError, который
    // молча проглотит try/catch — виджет навсегда останется с текстом '--'.
    parts.push('// Датчики создаются один раз в build(); переменные — на уровне модуля,');
    parts.push('// чтобы вспомогательные функции ниже их видели.');
    if (usesBattery) parts.push('let _battery = null;');
    if (usesStep) parts.push('let _step = null;');
    if (usesCalorie) parts.push('let _calorie = null;');
    if (usesDistance) parts.push('let _distance = null;');
    if (usesHeartRate) parts.push('let _heart = null;');
    parts.push('');
  }

  parts.push('WatchFace({');
  parts.push('  build() {');
  parts.push('    const self = this;');
  parts.push('');
  for (const line of buildLines) parts.push('    ' + line.replace(/\n/g, '\n    '));
  parts.push('');
  if (sensorImports.length) {
    parts.push('    // Датчики создаются один раз — try/catch на случай недоступности на симуляторе.');
    if (usesBattery) parts.push('    try { _battery = new Battery(); } catch (e) {}');
    if (usesStep) parts.push('    try { _step = new Step(); } catch (e) {}');
    if (usesCalorie) parts.push('    try { _calorie = new Calorie(); } catch (e) {}');
    if (usesDistance) parts.push('    try { _distance = new Distance(); } catch (e) {}');
    if (usesHeartRate) parts.push('    try { _heart = new HeartRate(); } catch (e) {}');
    parts.push('');
  }
  if (usesTimeHelpers) {
    parts.push('    function _tick() {');
    parts.push('      const now = new Date();');
    for (const line of timeUpdates) parts.push('      ' + line);
    parts.push('    }');
    parts.push('    _tick();');
    parts.push('    self._timeTimer = setInterval(_tick, 1000);');
    parts.push('');
  }
  if (sensorUpdates.length) {
    parts.push('    function _tickSensors() {');
    for (const line of sensorUpdates) parts.push('      ' + line);
    parts.push('    }');
    parts.push('    _tickSensors();');
    parts.push('    self._sensorTimer = setInterval(_tickSensors, 5000);');
    parts.push('');
  }
  if (secondSmooth && smoothLines.length) {
    const fps = Math.max(5, Math.min(60, jsNum(secondComp.props.smooth_fps, 20)));
    parts.push(`    self._smoothTimer = setInterval(() => {`);
    for (const line of smoothLines) parts.push('      ' + line);
    parts.push(`    }, ${Math.round(1000 / fps)});`);
    parts.push('');
  }
  parts.push('  },');
  parts.push('  onDestroy() {');
  parts.push('    if (this._timeTimer) { clearInterval(this._timeTimer); this._timeTimer = null; }');
  parts.push('    if (this._sensorTimer) { clearInterval(this._sensorTimer); this._sensorTimer = null; }');
  parts.push('    if (this._smoothTimer) { clearInterval(this._smoothTimer); this._smoothTimer = null; }');
  parts.push('  },');
  parts.push('});');
  parts.push('');

  const code = parts.join('\n');
  return { code, validation: { errors, warnings } };
}


// ---------------------------------------------------------------------------
// Dual Normal/AOD runtime exporter
//
// The editor keeps Normal and AOD as independent scenes.  Zepp OS, however,
// executes one WatchFace entry point and determines the current screen state
// at runtime.  Generate both scenes into the same watchface/index.js and build
// only the matching scene.  AOD widgets are created with the documented
// hmUI.show_level.ONAL_AOD display level.
// ---------------------------------------------------------------------------
function _extractWatchFaceParts(code) {
  const start = code.indexOf('WatchFace({');
  if (start < 0) throw new Error('Generated watchface code does not contain WatchFace({');
  const buildMarker = '  build() {\n';
  const buildStart = code.indexOf(buildMarker, start);
  const destroyMarker = '  onDestroy() {';
  const destroyStart = code.indexOf(destroyMarker, buildStart);
  if (buildStart < 0 || destroyStart < 0) throw new Error('Cannot extract generated build() body.');
  const bodyStart = buildStart + buildMarker.length;
  const body = code.slice(bodyStart, destroyStart).replace(/\n  },\n$/, '');
  const destroyEnd = code.indexOf('  },\n});', destroyStart);
  const destroyBody = code.slice(destroyStart + destroyMarker.length, destroyEnd);
  return {
    preamble: code.slice(0, start).trimEnd(),
    body,
    destroyBody,
  };
}

function _makeAodWidgetLevel(code) {
  // Every widget created by the AOD scene is explicitly restricted to the
  // screen-off/AOD state.  This also covers transparent BUTTON tap zones and
  // generated background/shape widgets.
  return code.replace(/createWidget\((widget\.[A-Za-z0-9_]+), \{\s*/g,
    (m) => m + 'show_level: hmUI.show_level.ONAL_AOD,\n');
}

function exportIndexJsDual(project, assetMap, fontMap, weatherAssetMap = {}) {
  // Normal всегда является главным экраном экспорта. Если Designer открыт в AOD,
  // project.components содержит AOD; поэтому Normal берём из сохранённой сцены.
  const normalScene = project.scenes?.normal || {};
  const normalComponents = Array.isArray(normalScene.components)
    ? normalScene.components
    : (project.mode === 'normal' && Array.isArray(project.components) ? project.components : []);
  const normalBackground = normalScene.background || (project.mode === 'normal' ? project.background : null) || { color: '#000000', imageAssetId: null, alpha: 100 };
  const aodScene = project.scenes?.aod || {};
  const aodComponents = (Array.isArray(aodScene.components) ? aodScene.components : [])
    // AOD: секундная аналоговая стрелка отключается только при экспорте AOD.
    // Normal-сцена и настройки редактора не изменяются.
    .filter((c) => c.defId !== 'time_pointer_second');

  // Generate the two scenes independently so every widget receives its own
  // display level, then place BOTH widget sets into the SAME WatchFace build.
  // The firmware decides what is visible from show_level; we do not branch the
  // entire scene at runtime. This is the documented Zepp OS watchface model.
  const unionIds = new Set();
  const unionComponents = [];
  for (const c of [...normalComponents, ...aodComponents]) {
    const key = `${c.id || ''}::${c.defId || ''}::${JSON.stringify(c.props || {})}`;
    if (unionIds.has(key)) continue;
    unionIds.add(key);
    unionComponents.push(JSON.parse(JSON.stringify(c)));
  }
  const unionProject = Object.assign({}, project, {
    components: unionComponents,
    background: project.background || { color: '#000000', imageAssetId: null, alpha: 100 },
  });

  const normalProject = Object.assign({}, project, {
    components: JSON.parse(JSON.stringify(normalComponents)),
    background: JSON.parse(JSON.stringify(normalBackground)),
  });
  const aodProject = Object.assign({}, project, {
    components: JSON.parse(JSON.stringify(aodComponents)),
    background: JSON.parse(JSON.stringify(aodScene.background || { color: '#000000', imageAssetId: null, alpha: 100 })),
  });

  // The union supplies the superset of imports, module-level sensor helpers and
  // constants. Normal/AOD bodies are namespaced to avoid duplicate const names.
  const base = exportIndexJs(unionProject, assetMap, fontMap, { namePrefix: 'u_', weatherAssetMap });
  const normal = exportIndexJs(normalProject, assetMap, fontMap, {
    namePrefix: 'normal_',
    showLevel: 'ONLY_NORMAL',
    weatherAssetMap,
  });
  const aod = exportIndexJs(aodProject, assetMap, fontMap, {
    namePrefix: 'aod_',
    showLevel: 'ONAL_AOD',
    weatherAssetMap,
  });

  const n = _extractWatchFaceParts(normal.code);
  const a = _extractWatchFaceParts(aod.code);
  const b = _extractWatchFaceParts(base.code);

  function renameTimers(body, suffix) {
    return body
      .replace(/_timeTimer/g, `_timeTimer${suffix}`)
      .replace(/_sensorTimer/g, `_sensorTimer${suffix}`)
      .replace(/_smoothTimer/g, `_smoothTimer${suffix}`)
      .replace(/function _tick\(/g, `function _tick${suffix}(`)
      .replace(/_tick\(/g, `_tick${suffix}(`)
      .replace(/function _tickSensors\(/g, `function _tickSensors${suffix}(`)
      .replace(/_tickSensors\(/g, `_tickSensors${suffix}(`);
  }

  const normalBody = renameTimers(n.body.replace(/const self = this;\s*/g, ''), 'Normal');
  const aodBody = renameTimers(a.body.replace(/const self = this;\s*/g, ''), 'Aod');

  const code = [
    b.preamble,
    '',
    '// Dual scene runtime: Normal and AOD are both exported into this one watchface.',
    '// Zepp OS controls visibility through the documented widget show_level property.',
    'WatchFace({',
    '  build() {',
    '    const self = this;',
    '',
    '    // Normal scene widgets',
    ...normalBody.split('\n').map(line => '    ' + line),
    '',
    '    // AOD scene widgets',
    ...aodBody.split('\n').map(line => '    ' + line),
    '  },',
    '  onDestroy() {',
    '    if (this._timeTimerNormal) { clearInterval(this._timeTimerNormal); this._timeTimerNormal = null; }',
    '    if (this._sensorTimerNormal) { clearInterval(this._sensorTimerNormal); this._sensorTimerNormal = null; }',
    '    if (this._smoothTimerNormal) { clearInterval(this._smoothTimerNormal); this._smoothTimerNormal = null; }',
    '    if (this._timeTimerAod) { clearInterval(this._timeTimerAod); this._timeTimerAod = null; }',
    '    if (this._sensorTimerAod) { clearInterval(this._sensorTimerAod); this._sensorTimerAod = null; }',
    '    if (this._smoothTimerAod) { clearInterval(this._smoothTimerAod); this._smoothTimerAod = null; }',
    '  },',
    '});',
    '',
  ].join('\n');

  const warnings = [
    ...(base.validation?.warnings || []),
    ...(normal.validation?.warnings || []).filter(w => !(base.validation?.warnings || []).includes(w)),
    ...(aod.validation?.warnings || []).filter(w => !(base.validation?.warnings || []).includes(w)),
  ];
  if (aodComponents.length === 0) {
    warnings.push('AOD-сцена пуста: добавьте элементы в AOD Studio. Normal при этом экспортируется независимо.');
  } else {
    warnings.push(`В один watchface/index.js экспортированы обе сцены: Normal (${normalComponents.length}) + AOD (${aodComponents.length}). Видимость задаётся show_level.ONLY_NORMAL / show_level.ONAL_AOD.`);
  }

  return {
    code,
    validation: {
      errors: [...(base.validation?.errors || []), ...(normal.validation?.errors || []), ...(aod.validation?.errors || [])],
      warnings: [...new Set(warnings)],
    },
  };
}
